# Measured loudness data (Grok #72, 12.11.2026): Markdown -> HTML for the data pages, values from genre_index.json.
# Exec'd by gen.py (shares its namespace: html, os, re, BASE ...). Sources in _tools/daten/ are copies of
# C:/traffic/seiten/ (texts by Session Traffic P6, tables generated by genre_index.py). Never edit numbers by hand:
# regenerate with genre_index.py and copy the files again.
import json as _json
import re

DATEN_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'daten')
with open(os.path.join(DATEN_DIR, 'genre_index.json'), encoding='utf-8') as _f:
    GENRE_INDEX = _json.load(_f)


def gi_wert(x, de=False):
    """Same formatting as genre_index.py f(): one decimal, typographic minus, decimal comma in German."""
    s = f'{x:.1f}'.replace('-', '−')
    return s.replace('.', ',') if de else s


def gi_genre(seite, key):
    for g in GENRE_INDEX['seiten'][seite]['haupt']:
        if g['key'] == key:
            return g
    raise KeyError(f'genre_index.json: {seite}/{key} missing')


def gi_lufs(seite, key, lang):
    """'median −8.0 LUFS (middle half −9.6 to −6.9), 16 releases' from genre_index.json."""
    g = gi_genre(seite, key)
    d = g['lufs_int']
    de = lang == 'de'
    if de:
        return f'Median {gi_wert(d["med"], True)} LUFS (mittlere Hälfte {gi_wert(d["p25"], True)} bis {gi_wert(d["p75"], True)}), {g["n_lufs"]} Releases'
    return f'median {gi_wert(d["med"])} LUFS (middle half {gi_wert(d["p25"])} to {gi_wert(d["p75"])}), {g["n_lufs"]} releases'


# ---------------------------------------------------------------- Markdown -> HTML (only what the data texts use)
def md_frontmatter(text):
    m = re.match(r'---\n(.*?)\n---\n', text, re.S)
    meta = {}
    for line in m.group(1).splitlines():
        k, _, v = line.partition(':')
        meta[k.strip()] = v.strip().strip('"')
    return meta, text[m.end():]


def md_inline(s):
    s = html.escape(s, quote=False)
    s = s.replace('\\*', '&#42;')
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    s = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', r'<a href="\2">\1</a>', s)
    return s


def md_bloecke(text):
    """Splits Markdown into blocks: ('h2', text) | ('p', text) | ('ul', [items]) | ('ol', [items]) | ('table', rows)."""
    text = re.sub(r'<!--.*?-->', '', text, flags=re.S)
    out = []
    for block in re.split(r'\n\s*\n', text.strip()):
        lines = [l for l in block.strip().splitlines() if l.strip()]
        if not lines:
            continue
        if lines[0].startswith('## '):
            out.append(('h2', lines[0][3:].strip()))
            lines = lines[1:]
            if not lines:
                continue
        if all(l.startswith('|') for l in lines):
            rows = [[c.strip() for c in l.strip().strip('|').split('|')] for l in lines if not re.match(r'^\|[\s|:-]+\|$', l)]
            out.append(('table', rows))
        elif all(l.startswith('- ') for l in lines):
            out.append(('ul', [l[2:] for l in lines]))
        elif all(re.match(r'\d+\. ', l) for l in lines):
            out.append(('ol', [re.sub(r'^\d+\. ', '', l) for l in lines]))
        else:
            out.append(('p', '\n'.join(lines)))
    return out


def md_block_html(b, ind='    '):
    typ, inhalt = b
    if typ == 'p':
        cls = ' class="table-note"' if inhalt.startswith('\\*') or inhalt.startswith('Not enough material') or inhalt.startswith('Für eine belastbare') or inhalt.startswith('Noch zu wenig') else ''
        return f'{ind}<p{cls}>{md_inline(inhalt).replace(chr(10), " ")}</p>'
    if typ in ('ul', 'ol'):
        return f'{ind}<{typ}>\n' + '\n'.join(f'{ind}  <li>{md_inline(i)}</li>' for i in inhalt) + f'\n{ind}</{typ}>'
    if typ == 'table':
        kopf, *rows = inhalt
        th = ''.join(f'<th scope="col">{md_inline(c)}</th>' for c in kopf)
        tr = '\n'.join(f'{ind}        <tr><th scope="row">{md_inline(r[0])}</th>' + ''.join(f'<td>{md_inline(c)}</td>' for c in r[1:]) + '</tr>' for r in rows)
        return (f'{ind}<div class="table-wrap">\n{ind}  <table>\n{ind}    <thead><tr>{th}</tr></thead>\n{ind}    <tbody>\n{tr}\n'
                f'{ind}    </tbody>\n{ind}  </table>\n{ind}</div>')
    raise ValueError(typ)


def md_faq(bloecke):
    """FAQ paragraphs '**Question?**\\nAnswer' -> [(q, a_html)]; other paragraphs are returned separately."""
    faqs, rest = [], []
    for b in bloecke:
        m = re.match(r'\*\*(.+?\?)\*\*\n(.+)', b[1], re.S) if b[0] == 'p' else None
        if m:
            faqs.append((m.group(1).strip(), md_inline(m.group(2).strip()).replace('\n', ' ')))
        else:
            rest.append(b)
    return faqs, rest


def datenseite_lesen(text_datei, tabellen_datei, ersatz=()):
    """Returns (meta, intro_blocks, sections[(h2, blocks)]) with the tables inserted at the TABELLEN marker."""
    with open(os.path.join(DATEN_DIR, text_datei), encoding='utf-8') as f:
        meta, body = md_frontmatter(f.read())
    for alt, neu in ersatz:
        assert body.count(alt) == 1, f'{text_datei}: replacement source not found: {alt[:50]}'
        body = body.replace(alt, neu)
    with open(os.path.join(DATEN_DIR, tabellen_datei), encoding='utf-8') as f:
        tabellen = f.read()
    marke = re.search(r'<!-- TABELLEN:[^>]*-->', body)
    assert marke, f'{text_datei}: TABELLEN marker missing'
    body = body[:marke.start()] + '\n\n' + tabellen + '\n\n' + body[marke.end():]
    intro, sections = [], []
    for b in md_bloecke(body):
        if b[0] == 'h2':
            sections.append((b[1], []))
        elif sections:
            sections[-1][1].append(b)
        else:
            intro.append(b)
    return meta, intro, sections


def kurz_ohne_label(kurz_html):
    """'<strong>Short answer:</strong> in our ...' -> 'In our ...' (the label is shown by the answer box)."""
    t = re.sub(r'^<strong>[^<]*</strong>\s*', '', kurz_html)
    return t[:1].upper() + t[1:]
